  "content": "import numpy as np

SPEED = {
    'wsa54': dict(v0=285.0, v1=625.0, a=2 / 9, w=2.0, b=2.0, c=3.0),
    'mcgregor11': dict(v0=240.0, v1=675.0, a=2 / 9, w=2.8, b=1.25, c=3.0),
    'euhforia': dict(v0=240.0, v1=675.0, a=0.222, w=np.degrees(0.02), b=1.25, c=3.0),
}

RULES = {
    'enlil': dict(vfast=700.0, vslow=200.0, vrfast=25.0, vrslow=75.0, bfast=350.0, dfast=125.0,
                  tfast=1.5e6, shift_deg=9.0),
    'euhforia': dict(dv=50.0, vmin=275.0, vmax=625.0, vfsw=675.0, bfsw=300.0, nfsw=300.0, tfsw=0.8e6,
                     shift_deg=0.0),
}


def speed(fs, thetab_deg, v0, v1, a, w, b, c):
    return v0 + v1 / (1.0 + fs) ** a * (1.0 - 0.8 * np.exp(-(thetab_deg / w) ** b)) ** c


def inner_boundary(v, polarity, rule, p):
    if rule == 'enlil':
        vc = np.clip(v, p['vslow'], p['vfast'])
        vr = vc - (p['vrslow'] + (p['vrfast'] - p['vrslow']) * (vc - p['vslow']) / (p['vfast'] - p['vslow']))
        n = p['dfast'] * (p['vfast'] / vr) ** 2
        T = p['tfast'] * p['dfast'] / n
        br = polarity * p['bfast']
    elif rule == 'euhforia':
        vr = np.clip(v - p['dv'], p['vmin'], p['vmax'])
        n = p['nfsw'] * (p['vfsw'] / vr) ** 2
        T = p['tfsw'] * p['nfsw'] / n
        br = polarity * p['bfsw'] * vr / p['vfsw']
    else:
        raise ValueError(rule)
    return vr, n, T, br
